// ──────────────────────────────────────────────────────────────────────────────
// Main
// ──────────────────────────────────────────────────────────────────────────────
async function main() {
  console.log("── Step 1: Setting categories on existing courses ──");
  for (const [slug, category] of Object.entries(existingCategories)) {
    await db.update(coursesTable).set({ category }).where(eq(coursesTable.slug, slug));
    process.stdout.write(".");
  }
  console.log(`\n✓ Updated ${Object.keys(existingCategories).length} existing courses with categories.`);

  console.log("\n── Step 2: Inserting new courses ──");
  for (const course of newCourses) {
    const existing = await db.select({ id: coursesTable.id }).from(coursesTable).where(eq(coursesTable.slug, course.slug));
    if (existing.length > 0) {
      console.log(`  ↷ Skipping ${course.name} (already exists)`);
      continue;
    }

    const [inserted] = await db.insert(coursesTable).values({
      name: course.name,
      slug: course.slug,
      description: course.description,
      icon: course.icon,
      category: course.category,
    }).returning({ id: coursesTable.id });

    await db.insert(questionsTable).values(
      course.questions.map((q) => ({
        courseId: inserted.id,
        level: q.level,
        text: q.text,
        options: q.options,
        correctOptionIndex: q.correctOptionIndex,
        explanation: q.explanation,
      }))
    );

    console.log(`  ✓ ${course.name} (${course.questions.length} questions)`);
  }

  console.log("\n✅ Done. New total:");
  const [{ count }] = await db.execute<{ count: string }>("SELECT COUNT(*)::int as count FROM courses");
  console.log(`   Courses: ${count}`);
  const [{ qcount }] = await db.execute<{ qcount: string }>("SELECT COUNT(*)::int as qcount FROM questions");
  console.log(`   Questions: ${qcount}`);
  process.exit(0);
}

main().catch((err) => { console.error(err); process.exit(1); });
